const msgs = {
  '3d': {
    1: "Oi! Vi que voce deu uma olhadinha nas cartelas 3D 😍 Ficou com alguma duvida sobre elas? Posso te ajudar a escolher!",
    2: "Ainda dando aquela olhada nas cartelas 3D? 👀 Essa promocao do kit com 15 cartelas e por tempo limitado, nao queria que voce perdesse!",
    3: "Oi! Passando pra lembrar da promocao das cartelas 3D que te mostrei mais cedo 💅 Se quiser garantir, e so me chamar que eu te passo todos os detalhes!"
  },
  artesanal: {
    1: "Oi! Curtiu as peliculas artesanais que te mandei? 😍 Qualquer duvida sobre os modelos ou tamanhos, e so falar comigo!",
    2: "Ainda pensando no cartelao artesanal? Essa promocao esta com um preco especial, nao queria que voce perdesse essa oportunidade 💕",
    3: "Oi! So passando pra lembrar da promocao do cartelao artesanal que te mostrei hoje. Se quiser fechar, me chama que eu ja preparo tudo pra voce 😊"
  },
  copa: {
    1: "Oi! Gostou do kit de casadinhas tema Copa? Se quiser saber mais sobre tamanhos ou valores, e so me chamar!",
    2: "Ainda dando uma olhada no kit casadinhas da Copa? Essa promocao e por tempo limitado e ta super em alta agora 🔥",
    3: "Oi! Passando pra lembrar do kit casadinhas tema Copa que te mostrei. Se quiser garantir o seu, me chama que eu te ajudo com tudo 💅"
  }
};

const generico = {
  1: "Oi! Vi que te mandei algumas fotos mais cedo 😊 Ficou com alguma duvida? Posso te ajudar!",
  2: "Ainda por ai? Fico a disposicao se quiser saber mais sobre os produtos que te mostrei 💕",
  3: "Oi! So passando pra lembrar das fotos que te enviei hoje. Qualquer duvida, me chama! 😊"
};

const item = $input.item.json;
const agora = new Date();

let followup = 0;
if (!item.followup_1_enviado && new Date(item.proximo_followup_1) <= agora) followup = 1;
else if (!item.followup_2_enviado && new Date(item.proximo_followup_2) <= agora) followup = 2;
else if (!item.followup_3_enviado && new Date(item.proximo_followup_3) <= agora) followup = 3;

if (!followup) return null;

const grupo = msgs[item.produto_interesse] || generico;
const mensagem = grupo[followup] || generico[followup];

return {
  json: {
    mensagem,
    followup,
    telefone: item.telefone,
    lead_id: item.id,
    evo_api_url: item.evo_api_url,
    evo_api_key: item.evo_api_key
  }
};
